"""Compressed byte sequences, byte expressions and template compilation.

Sequences are immutable trees that cache a logical length together with the
exact audit fingerprint hash, so very large compressed objects are combined,
sliced and fingerprinted without ever being expanded in memory.
"""
import ast
import hashlib

MAX = (1 << 63) - 1
MASK = (1 << 64) - 1
BASE = 257
RANDOM_TOKEN = '<<random_string>>'
EXPRESSION_LIMIT = 8192
TEMPLATE_LIMIT = 65536
AST_LIMIT = 128
FLATTEN_DEPTH = 24
FLATTEN_BYTES = 1 << 16
FLATTEN_BUDGET = 48 << 20

flatten_used = 0
_pow_cache = {}
_geo_cache = {}


def pow257(exponent):
    """257**exponent modulo 2**64, memoised for repeated slice arithmetic."""
    got = _pow_cache.get(exponent)
    if got is None:
        got = pow(BASE, exponent, MASK)
        if len(_pow_cache) > 4096:
            _pow_cache.clear()
        _pow_cache[exponent] = got
    return got


def geo(count, base):
    """Sum of base**i for i in range(count) modulo 2**64 in logarithmic time."""
    if count <= 0:
        return 0
    total = 0
    block = 1
    for bit in bin(count)[2:]:
        total = total * (1 + block) & MASK
        block = block * block & MASK
        if bit == '1':
            total = (total + block) & MASK
            block = block * base & MASK
    return total


def base_geo(count):
    got = _geo_cache.get(count)
    if got is None:
        got = geo(count, BASE)
        if len(_geo_cache) > 4096:
            _geo_cache.clear()
        _geo_cache[count] = got
    return got


def horner(data, initial=0):
    h = initial
    for byte in data:
        h = (h * BASE + byte) & MASK
    return h


def digest_bytes(data):
    """Exact fingerprint hash of a raw byte string."""
    return (horner(data) + base_geo(len(data))) & MASK


def hexdigest(digest):
    return '%016x' % digest


def fingerprint(node):
    """Requested exact checksum record for a byte sequence."""
    return {'n': node.length, 'h': hexdigest(node.hash)}


def fingerprint_bytes(data):
    return {'n': len(data), 'h': hexdigest(digest_bytes(data))}


class Seq:
    """Base compressed byte sequence with cached length, hash and tree depth."""

    __slots__ = ('length', 'hash', 'depth')

    def __init__(self, length, digest, depth):
        if length > MAX:
            raise ValueError('sequence length budget')
        self.length = length
        self.hash = digest
        self.depth = depth


class Lit(Seq):
    __slots__ = ('data', 'memo')

    def __init__(self, data):
        self.data = data
        self.length = len(data)
        self.hash = digest_bytes(data)
        self.depth = 0
        self.memo = None


class Cat(Seq):
    __slots__ = ('left', 'right')

    def __init__(self, left, right):
        length = left.length + right.length
        if length > MAX:
            raise ValueError('sequence length budget')
        self.left = left
        self.right = right
        self.length = length
        self.hash = (left.hash * pow257(right.length) + right.hash) & MASK
        self.depth = (left.depth if left.depth > right.depth else right.depth) + 1


class Rep(Seq):
    __slots__ = ('base', 'count')

    def __init__(self, base, count):
        length = base.length * count
        if length > MAX:
            raise ValueError('sequence length budget')
        self.base = base
        self.count = count
        self.length = length
        self.hash = base.hash * geo(count, pow257(base.length)) & MASK
        self.depth = base.depth + 1


class Cut(Seq):
    __slots__ = ('base', 'start', 'stop')

    def __init__(self, base, start, stop):
        self.base = base
        self.start = start
        self.stop = stop
        self.length = stop - start
        self.hash = hash_range(base, start, stop)
        self.depth = base.depth + 1


EMPTY = None


def literal(data):
    if type(data) is not bytes:
        if isinstance(data, (bytearray, memoryview)):
            data = bytes(data)
        else:
            raise ValueError('literal bytes')
    return Lit(data)


def text_bytes(value):
    """UTF-8 encoding of a template literal, rejecting lone surrogates."""
    return value.encode('utf-8')


def concat(left, right):
    if left.length == 0:
        return right
    if right.length == 0:
        return left
    return Cat(left, right)


def repeat(node, count):
    if type(count) is not int or isinstance(count, bool):
        raise ValueError('repetition count')
    if count < 0:
        raise ValueError('negative repetition')
    if count == 0 or node.length == 0:
        return Lit(b'')
    if count == 1:
        return node
    return Rep(node, count)


def cut(node, start, stop):
    if type(start) is not int or type(stop) is not int:
        raise ValueError('slice bounds')
    if start < 0 or stop < start or stop > node.length:
        raise ValueError('slice bounds')
    if start == 0 and stop == node.length:
        return node
    if start == stop:
        return Lit(b'')
    return Cut(node, start, stop)


def size(node):
    return node.length


def read(node, lo, hi):
    """Materialise the byte window node[lo:hi]; windows stay small."""
    if hi <= lo:
        return b''
    kind = node.__class__
    if kind is Lit:
        return node.data[lo:hi]
    if kind is Cat:
        split = node.left.length
        if hi <= split:
            return read(node.left, lo, hi)
        if lo >= split:
            return read(node.right, lo - split, hi - split)
        return read(node.left, lo, split) + read(node.right, 0, hi - split)
    if kind is Cut:
        start = node.start
        return read(node.base, lo + start, hi + start)
    if kind is Rep:
        base = node.base
        step = base.length
        first = lo // step
        last = (hi - 1) // step
        if first == last:
            offset = lo - first * step
            return read(base, offset, offset + (hi - lo))
        if base.__class__ is Lit:
            pattern = base.data
            out = bytearray(pattern[lo - first * step:])
            for _ in range(last - first - 1):
                out += pattern
            out += pattern[:hi - last * step]
            return bytes(out)
        out = bytearray(read(base, lo - first * step, step))
        for _ in range(last - first - 1):
            out += read(base, 0, step)
        out += read(base, 0, hi - last * step)
        return bytes(out)
    raise ValueError('sequence type')


def hash_range(node, lo, hi):
    """Exact fingerprint hash of node[lo:hi]."""
    if lo >= hi:
        return 0
    if lo == 0 and hi == node.length:
        return node.hash
    kind = node.__class__
    if kind is Lit:
        memo = node.memo
        if memo is None:
            memo = node.memo = {}
        key = (lo, hi)
        got = memo.get(key)
        if got is None:
            got = (horner(node.data[lo:hi]) + base_geo(hi - lo)) & MASK
            if len(memo) > 8:
                memo.clear()
            memo[key] = got
        return got
    if kind is Cat:
        split = node.left.length
        if hi <= split:
            return hash_range(node.left, lo, hi)
        if lo >= split:
            return hash_range(node.right, lo - split, hi - split)
        return (hash_range(node.left, lo, split) * pow257(hi - split)
                + hash_range(node.right, 0, hi - split)) & MASK
    if kind is Cut:
        start = node.start
        return hash_range(node.base, lo + start, hi + start)
    if kind is Rep:
        base = node.base
        step = base.length
        first = lo // step
        last = (hi - 1) // step
        if first == last:
            offset = lo - first * step
            return hash_range(base, offset, offset + (hi - lo))
        offset = lo - first * step
        tail = hi - last * step
        full = (last - first + 1) - (1 if offset else 0) - (1 if tail < step else 0)
        result = 0
        covered = 0
        if offset:
            result = hash_range(base, offset, step)
            covered = step - offset
        if full:
            block = base.hash * geo(full, pow257(step)) & MASK
            result = (result * pow257(full * step) + block) & MASK
            covered += full * step
        if tail < step:
            result = (result * pow257(tail) + hash_range(base, 0, tail)) & MASK
            covered += tail
        if covered != hi - lo:
            raise ValueError('slice coverage')
        return result
    raise ValueError('sequence type')


def materialize(node, limit=65536):
    if node.length > limit:
        raise ValueError('bounded materialization')
    return read(node, 0, node.length)


def next_lf(node, start=0):
    """Offset of the first LF at or after start, or -1 when none exists."""
    window = 64
    total = node.length
    while start < total:
        stop = min(total, start + window)
        block = read(node, start, stop)
        found = block.find(b'\n')
        if found >= 0:
            return start + found
        if stop >= total:
            return -1
        if window >= 8194:
            return -1
        start = stop
        window = min(window * 8, 8194)
    return -1


def maybe_flatten(node):
    """Collapse deep trees whose result is small, keeping big objects lazy."""
    global flatten_used
    if node.depth <= FLATTEN_DEPTH or node.length > FLATTEN_BYTES:
        return node
    if flatten_used >= FLATTEN_BUDGET:
        return node
    data = read(node, 0, node.length)
    flatten_used += len(data)
    return Lit(data)


EMPTY = Lit(b'')


def empty_fingerprint():
    return {'n': 0, 'h': '0000000000000000'}


def ast_depth(node):
    best = 0
    for child in ast.iter_child_nodes(node):
        depth = ast_depth(child) + 1
        if depth > best:
            best = depth
    return best


def is_definition_name(name):
    import keyword
    if type(name) is not str or not name or len(name) > 32:
        return False
    if keyword.iskeyword(name):
        return False
    head = name[0]
    if not ('A' <= head <= 'Z' or 'a' <= head <= 'z'):
        return False
    return all(c == '_' or 'A' <= c <= 'Z' or 'a' <= c <= 'z' or '0' <= c <= '9'
               for c in name[1:])


class Mixer:
    """Incremental fingerprint accumulator over concatenated sequences."""

    __slots__ = ('length', 'hash')

    def __init__(self):
        self.length = 0
        self.hash = 0

    def add(self, node):
        count = node.length
        if count:
            if self.length + count > MAX:
                raise ValueError('receipt length budget')
            self.hash = (self.hash * pow257(count) + node.hash) & MASK
            self.length += count

    def add_bytes(self, data):
        if data:
            self.add(Lit(data))

    def add_hash(self, count, digest):
        if count:
            if self.length + count > MAX:
                raise ValueError('receipt length budget')
            self.hash = (self.hash * pow257(count) + digest) & MASK
            self.length += count

    def add_span(self, capture, lo, hi):
        self.add_hash(hi - lo, capture.hash_span(lo, hi))

    def add_int(self, value, width=8):
        self.add_bytes(value.to_bytes(width, 'big'))

    def result(self):
        return {'n': self.length, 'h': hexdigest(self.hash)}


def write_field_block(mixer, pairs):
    mixer.add_int(len(pairs))
    for name, value in pairs:
        mixer.add_int(len(name))
        mixer.add_bytes(name)
        mixer.add_int(len(value))
        mixer.add_bytes(value)


class Context:
    """Shared byte definitions plus template compilation."""

    def __init__(self, definitions, seed):
        self.seed = seed
        self.values = {}
        for name, source in definitions:
            if name in self.values:
                raise ValueError('duplicate definition')
            self.values[name] = maybe_flatten(self.expression(source))

    def expression(self, source):
        if type(source) is not str:
            raise ValueError('expression type')
        if len(source) > EXPRESSION_LIMIT:
            raise ValueError('expression source budget')
        try:
            tree = ast.parse(source, mode='eval')
        except Exception:
            raise ValueError('expression syntax') from None
        if ast_depth(tree.body) > AST_LIMIT:
            raise ValueError('expression depth budget')
        return self.build(tree.body)

    def scalar(self, node):
        if type(node) is ast.Constant:
            value = node.value
            if type(value) is int and not isinstance(value, bool) and 0 <= value <= MAX:
                return value
        return None

    def bound(self, node, default):
        if node is None:
            return default
        value = self.scalar(node)
        if value is None:
            raise ValueError('slice endpoint')
        return value

    def build(self, node):
        if type(node) is ast.Constant:
            value = node.value
            if type(value) is bytes:
                return Lit(value)
            if type(value) is str:
                return Lit(value.encode('utf-8'))
            raise ValueError('expression must be bytes')
        if type(node) is ast.Name:
            try:
                return self.values[node.id]
            except (KeyError, TypeError):
                raise ValueError('unknown definition') from None
        if type(node) is ast.BinOp:
            op = node.op
            if type(op) is ast.Add:
                return concat(self.build(node.left), self.build(node.right))
            if type(op) is ast.Mult:
                left = self.scalar(node.left)
                right = self.scalar(node.right)
                if left is not None and right is None:
                    return repeat(self.build(node.right), left)
                if right is not None and left is None:
                    return repeat(self.build(node.left), right)
                raise ValueError('repetition operands')
            raise ValueError('unsupported operator')
        if type(node) is ast.Subscript:
            target = node.slice
            if type(target) is not ast.Slice or target.step is not None:
                raise ValueError('slice form')
            value = self.build(node.value)
            return cut(value, self.bound(target.lower, 0),
                       self.bound(target.upper, value.length))
        raise ValueError('unsupported expression syntax')

    def template(self, value, coordinate):
        if type(value) is not str:
            raise ValueError('template type')
        if len(value) > TEMPLATE_LIMIT:
            raise ValueError('template source budget')
        if value.startswith('{{') and value.endswith('}}') and len(value) > 3:
            return maybe_flatten(self.expression(value[2:-2].strip()))
        return self.literal_template(value, coordinate)

    def literal_template(self, value, coordinate):
        data = value.encode('utf-8')
        if RANDOM_TOKEN not in value:
            return Lit(data)
        parts = []
        occurrence = 0
        pos = 0
        prefix = self.seed + '/' + coordinate + '/'
        while True:
            found = value.find(RANDOM_TOKEN, pos)
            if found < 0:
                parts.append(value[pos:])
                break
            parts.append(value[pos:found])
            parts.append(hashlib.sha256(
                (prefix + str(occurrence)).encode('utf-8')).hexdigest()[:20])
            occurrence += 1
            pos = found + len(RANDOM_TOKEN)
        return Lit(''.join(parts).encode('utf-8'))
